// Carriers re-send delivery events, sometimes days apart. The order id is
// the idempotency key: the next two nodes drop any order that is already
// queued, and the hourly sweep skips anything already marked sent. Without
// this the same customer gets asked three times and unsubscribes.
const out = [];
for (const item of $input.all()) {
  const b = item.json.body ?? item.json;
  const orderId = String(b.order_id ?? '').trim();
  const email = String(b.email ?? '').trim().toLowerCase();
  if (!orderId || !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)) continue;
  if (String(b.status ?? '').toLowerCase() !== 'delivered') continue;
  // Ask after the customer has actually used the product, not the day it lands.
  const WAIT_DAYS = 7;
  const sendAfter = new Date(Date.now() + WAIT_DAYS * 864e5);
  out.push({ json: {
    orderId,
    email,
    firstName: String(b.first_name ?? '').trim(),
    product: String(b.product ?? '').trim(),
    timezone: String(b.timezone ?? '').trim() || 'Europe/London',
    deliveredAt: new Date().toISOString(),
    sendAfter: sendAfter.toISOString().slice(0, 10),
    status: 'pending'
  }});
}
return out;

// An order already in the queue is left exactly as it is. Writing it again
// would reset a "sent" row back to "pending" and restart the wait, and the
// customer would be asked a second time.
const existing = new Set(
  $('Look up existing orders').all()
    .map(i => String(i.json.orderId ?? '').trim())
    .filter(Boolean)
);
const out = [];
for (const item of $('Normalise and set wait').all()) {
  const id = item.json.orderId;
  if (existing.has(id)) continue;
  existing.add(id);   // the same order twice in one batch is queued once
  out.push({ json: item.json });
}
return out;

// Four independent reasons not to send. Each one is a real complaint if you
// get it wrong, so they are checked explicitly rather than folded into one
// clever condition.
const queue = $('Read queue').all().map(i => i.json);
const suppressed = new Set(
  $('Read suppression list').all()
    .map(i => String(i.json.email ?? '').trim().toLowerCase())
    .filter(Boolean)
);
const today = new Date().toISOString().slice(0, 10);
const seen = new Set();
const out = [];
for (const row of queue) {
  const email = String(row.email ?? '').trim().toLowerCase();
  const orderId = String(row.orderId ?? '').trim();
  if (!email || !orderId) continue;
  if (seen.has(orderId)) continue;                            // a stray duplicate row is sent once, not twice
  if (String(row.status ?? '') !== 'pending') continue;      // 1. already sent
  if (suppressed.has(email)) continue;                        // 2. unsubscribed, or already reviewed
  if (String(row.sendAfter ?? '') > today) continue;          // 3. still inside the wait
  // 4. Send inside the recipient's waking hours. Their timezone, not ours.
  let localHour;
  try {
    localHour = Number(new Intl.DateTimeFormat('en-GB', {
      hour: 'numeric', hourCycle: 'h23', timeZone: row.timezone || 'Europe/London'
    }).format(new Date()));
  } catch (e) {
    localHour = 10; // unknown timezone: treat as sendable rather than stranding the row forever
  }
  if (localHour < 9 || localHour > 18) continue;
  seen.add(orderId);
  out.push({ json: { ...row, orderId, email } });
}
return out;

// Keep only the rows whose email actually went out. Gmail returns one item
// per input, in order, so results pair with the rows by index. A failed send
// stays "pending" and is retried on the next sweep, and it does not stop the
// rest of the batch being sent and marked.
const rows = $('Due, opted in, civil hour').all();
const out = [];
$input.all().forEach((item, i) => {
  if (item.json.error || !item.json.id || !rows[i]) return;
  out.push({ json: { orderId: rows[i].json.orderId } });
});
return out;
